/*
 * Shared definitions between the xdpl2 BPF programs and userspace.
 * Userspace (Go) gets matching types generated by bpf2go; keep the layouts
 * explicit (no implicit padding) so both sides agree.
 */
#ifndef XDPL2_H
#define XDPL2_H

#include <linux/types.h>

#define XDPL2_MAX_PORTS 1024 /* port id 0 is reserved for the host stack */
#define XDPL2_HOST_PORT 0

/* Largest frame copied to the flood ring buffer (covers 1500 MTU + VLAN). */
#define XDPL2_MAX_FLOOD_LEN 2048

enum xdpl2_port_kind {
	XDPL2_PORT_NONE = 0,
	XDPL2_PORT_HOST = 1, /* host network stack, reached via the uplink */
	XDPL2_PORT_POD = 2,  /* host-side end of a pod veth pair */
};

enum xdpl2_origin {
	XDPL2_ORIGIN_UPLINK = 1, /* received from the wire (XDP on uplink) */
	XDPL2_ORIGIN_HOST = 2,   /* sent by the host stack (TCX egress on uplink) */
	XDPL2_ORIGIN_PORT = 3,   /* sent by a pod (TC ingress on its host veth) */
};

/* Key of the "ports" map (forwarding database). */
struct fdb_key {
	__u8 mac[6];
	__u16 vlan; /* 0 = untagged */
};

/* Value of the "ports" map. */
struct fdb_val {
	__u32 port_id;
};

/* Entry of the "port_table" array, indexed by port id. */
struct port {
	__u32 ifindex; /* host-side veth (pods) or uplink (host port) */
	__u16 vlan;    /* access VLAN, 0 = untagged */
	__u8 kind;     /* enum xdpl2_port_kind */
	__u8 flags;
	__u8 mac[6];   /* the one MAC this port may source frames from */
	__u8 pad[2];
};

/* Single-entry "config" array. */
struct config {
	__u32 uplink_ifindex;
	__u32 flags;
	__u8 host_mac[6];
	__u8 pad[2];
};

/* Record pushed to the "flood_rb" ring buffer for userspace replication. */
struct flood_event {
	__u32 len;      /* bytes valid in data[] */
	__u32 src_port; /* port id of the sender (ORIGIN_PORT only) */
	__u16 vlan;     /* VLAN the frame belongs to, 0 = untagged */
	__u8 origin;    /* enum xdpl2_origin */
	__u8 tagged;    /* 1 if data[] still carries an 802.1Q tag */
	__u32 pad;
	__u8 data[XDPL2_MAX_FLOOD_LEN];
};

enum xdpl2_stat {
	STAT_XDP_RX = 0,
	STAT_XDP_REDIRECT,
	STAT_XDP_PASS,
	STAT_XDP_FLOOD,
	STAT_XDP_LOOP_PASS,
	STAT_PORT_RX,
	STAT_PORT_TO_PORT,
	STAT_PORT_TO_HOST,
	STAT_PORT_TO_UPLINK,
	STAT_PORT_FLOOD,
	STAT_PORT_DROP_SPOOF,
	STAT_PORT_DROP_UNKNOWN,
	STAT_PORT_DROP_TAGGED,
	STAT_PORT_DROP_HAIRPIN,
	STAT_UPLINK_EGRESS_TO_PORT,
	STAT_UPLINK_EGRESS_FLOOD,
	STAT_FLOOD_RB_FULL,
	STAT_FLOOD_TOO_BIG,
	STAT_PARSE_ERROR,
	STAT_REDIRECT_ERROR,
	STAT__MAX,
};

#endif /* XDPL2_H */
